]$extras$::jsonb) as x(work_id uuid, titulo text, reviews jsonb, ressalva text);

drop table if exists pg_temp.mig214_antes;
create temp table mig214_antes on commit drop as
  select (select md5(coalesce(string_agg(concat_ws(':', work_id, criterion_slug, score, source, ai_evaluation_id), ',' order by work_id, criterion_slug), ''))
            from public.category_scores) as notas,
         (select md5(coalesce(string_agg(concat_ws(':', id, is_adult, adult_override, edition_state, r19_edition), ',' order by id), ''))
            from public.works) as obras,
         (select md5(coalesce(string_agg(concat_ws(':', work_id, tag_id), ',' order by work_id, tag_id), ''))
            from public.work_tags) as vinculos,
         (select md5(coalesce(string_agg(concat_ws(':', work_id, state, basis, decided_by), ',' order by work_id), ''))
            from public.work_edition_state) as estado;

-- ── 0) Guardas de ENTRADA ────────────────────────────────────────────────────────────────────
do $guarda$
declare n int; n_mixed int; n_fora int; n_falta int; n_legado int;
begin
  if to_regclass('public.work_edition_scores') is null then
    raise exception 'mig 214: a 213 não está aplicada — abortando';
  end if;
  select count(distinct work_id) into n from pg_temp.mig214_dados;
  if n <> 140 or (select count(*) from pg_temp.mig214_dados) <> 280 or (select count(*) from pg_temp.mig214_extras) <> 3 then
    raise exception 'mig 214: dado embutido inconsistente (% obras) — abortando', n;
  end if;
  if not ((select count(*) from pg_temp.mig214_dados where edition = 'normal' and source = 'inferred_base') = 127 and (select count(*) from pg_temp.mig214_dados where edition = 'normal' and source = 'not_rated') = 12 and (select count(*) from pg_temp.mig214_dados where edition = 'normal' and source = 'reused_existing') = 1 and (select count(*) from pg_temp.mig214_dados where edition = 'r18' and source = 'not_rated') = 58 and (select count(*) from pg_temp.mig214_dados where edition = 'r18' and source = 'reused_existing') = 82) then
    raise exception 'mig 214: as contagens por (edição, origem) do dado embutido não são as auditadas — abortando';
  end if;
  select count(*) into n_mixed from public.works where edition_state = 'mixed';
  select count(*) into n_fora from (select distinct work_id from pg_temp.mig214_dados) d
    left join public.works w on w.id = d.work_id where w.edition_state is distinct from 'mixed';
  select count(*) into n_falta from public.works w where w.edition_state = 'mixed'
    and not exists (select 1 from pg_temp.mig214_dados d where d.work_id = w.id);
  if n_mixed <> 140 or n_fora > 0 or n_falta > 0 then
    raise exception 'mig 214: o conjunto mixed do banco (%) não é o auditado: % fora, % sem dado — abortando', n_mixed, n_fora, n_falta;
  end if;
  -- A nota legada tem de ser a que a auditoria leu: se mudou, a atribuição por edição foi feita sobre
  -- outro número e tem de ser refeita.
  select count(*) into n_legado from (select distinct work_id, legado_score from pg_temp.mig214_dados) d
    left join public.category_scores cs on cs.work_id = d.work_id and cs.criterion_slug = 'adult_content'
   where cs.score is distinct from d.legado_score;
  if n_legado > 0 then
    raise exception 'mig 214: % obra(s) com adult_content diferente do auditado — refazer a auditoria; abortando', n_legado;
  end if;
  -- As 3 marcas de extras: obra mixed e (ainda) sem a marca — ou já marcada por esta migration.
  select count(*) into n from pg_temp.mig214_extras e join public.work_edition_state s on s.work_id = e.work_id
   where s.state = 'mixed' and (not s.r18_extra_chapters or s.evidence ? 'extras_r19_mig214');
  if n <> 3 then
    raise exception 'mig 214: só % de 3 obras de extras estão como auditado (mixed, sem marca) — abortando', n;
  end if;
end
$guarda$;

-- ── 1) As 3 marcas de extras R19 ─────────────────────────────────────────────────────────────
create schema if not exists bkp;
create table if not exists bkp.mig214_estado_antes as
  select s.work_id, s.r18_extra_chapters, s.evidence
    from public.work_edition_state s join pg_temp.mig214_extras e on e.work_id = s.work_id;

update public.work_edition_state s
   set r18_extra_chapters = true,
       evidence = s.evidence || jsonb_build_object('extras_r19_mig214', jsonb_strip_nulls(jsonb_build_object(
         'motivo', 'reviews dizem que o conteúdo sexual explícito está nos extras/side stories',
         'reviews', e.reviews, 'ressalva', e.ressalva, 'decidido_em', '2026-10-11')))
  from pg_temp.mig214_extras e
 where s.work_id = e.work_id and s.state = 'mixed' and not s.r18_extra_chapters;

-- ── 2) As 280 linhas ─────────────────────────────────────────────────────────────────────────
insert into public.work_edition_scores
  (work_id, edition, criterion_slug, score, source, status, confidence, ai_evaluation_id, evidence, decided_by)
select d.work_id, d.edition, 'adult_content', d.score, d.source,
       case d.source when 'not_rated' then 'not_rated' when 'inferred_base' then 'provisional' else 'rated' end,
       d.confidence, d.ai_evaluation_id, d.evidence, d.decided_by
  from pg_temp.mig214_dados d
on conflict (work_id, edition, criterion_slug) do nothing;

-- ── 3) Guardas de SAÍDA ──────────────────────────────────────────────────────────────────────
do $saida$
declare n_ok int; a record;
begin
  -- Toda linha auditada existe: igual ao dado, ou já substituída por uma fonte MAIS FORTE (curadoria
  -- posterior). Nada mais fraco, nada a menos.
  select count(*) into n_ok from pg_temp.mig214_dados d
    join public.work_edition_scores s on s.work_id = d.work_id and s.edition = d.edition and s.criterion_slug = 'adult_content'
   where (s.source = d.source and s.score is not distinct from d.score)
      or public.work_edition_score_strength(s.source) > public.work_edition_score_strength(d.source);
  if n_ok <> 280 then
    raise exception 'mig 214: só % de 280 linhas conferem com o dado auditado — abortando', n_ok;
  end if;
  if (select count(*) from pg_temp.mig214_dados where score is not null) <> 210
     or exists (select 1 from public.work_edition_scores where source = 'not_rated' and (score is not null or status <> 'not_rated' or confidence is not null)) then
    raise exception 'mig 214: as 70 linhas sem nota não são ausências explícitas (score NULL, not_rated, sem confiança) — abortando';
  end if;
  if (select count(*) from public.work_edition_state where state = 'mixed' and r18_extra_chapters) <> 10 then
    raise exception 'mig 214: esperava 10 obras mixed com extras R19 (7 da fase 1 + 3) — abortando';
  end if;
  select * into a from pg_temp.mig214_antes;
  if a.notas <> (select md5(coalesce(string_agg(concat_ws(':', work_id, criterion_slug, score, source, ai_evaluation_id), ',' order by work_id, criterion_slug), ''))
                   from public.category_scores) then
    raise exception 'mig 214: category_scores mudou — abortando';
  end if;
  if a.obras <> (select md5(coalesce(string_agg(concat_ws(':', id, is_adult, adult_override, edition_state, r19_edition), ',' order by id), ''))
                   from public.works) then
    raise exception 'mig 214: works (gate/override/estado) mudou — abortando';
  end if;
  if a.vinculos <> (select md5(coalesce(string_agg(concat_ws(':', work_id, tag_id), ',' order by work_id, tag_id), ''))
                      from public.work_tags) then
    raise exception 'mig 214: work_tags mudou — abortando';
  end if;
  if a.estado <> (select md5(coalesce(string_agg(concat_ws(':', work_id, state, basis, decided_by), ',' order by work_id), ''))
                    from public.work_edition_state) then
    raise exception 'mig 214: o estado de edição (state/basis/decided_by) mudou — abortando';
  end if;
  raise notice 'mig 214: 280 linhas por edição = 210 com nota + 70 não avaliado (normal 1 real · 127 baseline · 12 sem nota; R18 82 · 58 sem nota) · 3 marcas de extras';
end
$saida$;
